/* ---------------------------------------------- \xAB\u0421\u043D\u0438\u043C\u043E\u043A \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0435\xBB (2.7) */
